import {SCENES,REASONS} from './scenes.js';
import {newGame,commit,advance,allowedStakes,maxStake,riskLeft,INITIAL,RISK_BUDGET,pnlFor} from './engine.js';
const app=document.querySelector('#app');
let game=null,investigated=false,replayIndex=0;
const money=n=>'¥'+(n/100).toLocaleString('zh-CN',{maximumFractionDigits:2});
const signed=n=>(n>0?'+':n<0?'−':'')+money(Math.abs(n));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nl=s=>esc(s).replaceAll('\n','<br>');
const icon='<span class="brand-mark" aria-hidden="true">d<span>·</span></span>';
function header(){return `<header class="site-header"><a class="brand" href="#" data-action="home">${icon}<span>决策实验室<small>DECISION LAB / 001</small></span></a><div class="header-right"><span class="simulation-dot"></span><span>纯虚构模拟</span>${game?'<button class="text-button" data-action="reset">重新开始</button>':'<span class="edition">试玩版 v1.0</span>'}</div></header>`;}
const disclaimer=`<footer class="site-footer"><span>决策实验室 · 一次关于理由与运气的小实验</span><span>教学模型 ≠ 现实预测 · 无真实交易</span></footer>`;
function render(focus=true){app.innerHTML=header()+(game?(game.phase==='decision'?decisionPage():game.phase==='result'?resultPage():summaryPage()):intro())+disclaimer;bind();if(focus){document.querySelector('main')?.focus();window.scrollTo({top:0,behavior:'instant'});}}
function intro(){return `<main id="main" tabindex="-1" class="landing">
 <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="pill">约 15 分钟</span><span>5 次决定 · 很多种可能</span></div><h1>你赚了钱，<br>但你真的<br><em>做对了吗？</em></h1><p class="hero-description">结果会讲故事。<br>这次，我们先听听你的理由。</p><p class="hero-support">带着一笔虚构资金走过五个情景。留下决定，<br class="desktop-break">再把同一个选择，放进不同的运气里。</p><button class="primary start-button" data-action="start">进入实验 <span aria-hidden="true">↗</span></button><p class="microcopy">不用注册 · 不连接账户 · 等待也是一个选择</p></div>
 <div class="hero-art" role="img" aria-label="同一个决定分成不同的模拟路径：可能赚钱，也可能亏钱，决策理由在结果揭晓前已经写下。"><div class="art-grid"></div><span class="art-stamp">SAME CHOICE.<br>DIFFERENT LUCK.</span><div class="art-card decision-note"><span class="tiny-label">先留下</span><b>我的决定</b><div class="note-lines"><i></i><i></i><i></i></div><span class="handwritten">理由，不只是感觉。</span></div><svg class="branch-lines" viewBox="0 0 520 500" aria-hidden="true"><path d="M220 270 C300 270 245 115 370 115"/><path d="M220 270 C320 270 280 360 380 360"/><path d="M220 270 L400 245"/></svg><div class="art-card result-up"><span>路径 A / 模拟</span><b>赚了。</b><small>可能是好决定，也可能是好运。</small><span class="art-arrow">↗</span></div><div class="art-card result-down"><span>路径 B / 模拟</span><b>亏了。</b><small>一次结果，无法给理由盖章。</small><span class="art-arrow">↘</span></div><div class="small-orbit">?</div><div class="art-caption"><span>01</span>决定先写下，结果后揭晓。</div></div></section>
 <section class="intro-bottom" aria-label="实验说明"><div><span class="step-number">01</span><h2>先保住生活</h2><p>¥20,000 虚构本金。<br>房租和必要开支有自己的位置。</p></div><div><span class="step-number">02</span><h2>把理由放在前面</h2><p>新闻、推销、AI 建议。<br>你可以投资、调查，也可以等。</p></div><div><span class="step-number">03</span><h2>让运气换条路</h2><p>同一个决定，五条模拟路径。<br>复盘当时依据，不给人贴标签。</p></div></section>
 <details class="model-details"><summary>开始前：模型规则、隐私与局限</summary><div class="details-content"><p>全部公司、角色、新闻、金额和概率均为虚构教学设定，不是投资建议、现实预测或真实资产推荐。约 15 分钟是阅读与反思时间估计，没有限时压力。</p><p>每轮投入在本轮结束统一结算，没有跨轮持仓。现金收益设为零；不模拟税费、滑点、通胀、真实市场结构或长期投资。每轮最多投入 ¥3,000。整局 ¥6,000 损失预算按已发生的亏损累计扣减，盈利不回补预算；每次投入本金也不得超过剩余预算。</p><p>模型全部概率可在每轮决定前查看。结果由实验编号和轮次确定；回放不会偷偷换结果。五条路径是有放回的模型抽样，可能重复，不代表现实频率。</p><p>所有游戏记录只保存在当前页面内存，刷新即清空；可主动下载到本机。应用无账户、Cookie、第三方分析或联网 AI，不索取真实资产和身份信息。应用不读写 Cookie；公开托管平台会设置访客标识和安全 Cookie，并可能保留基本访问日志。游戏决定和笔记不会上传。本试玩的教学效果尚未验证。</p><label for="seed">实验编号（重放相同结果，可自行更改）</label><input id="seed" maxlength="32" value="FIRST-LIGHT" autocomplete="off" spellcheck="false" pattern="[A-Za-z0-9-]{1,32}" aria-describedby="seed-help"><small id="seed-help">仅用字母、数字或短横线，不要填写姓名、账号等个人信息。</small></div></details><p id="intro-error" class="error" role="alert"></p>
 </main>`;}
function progress(){return `<nav class="progress" aria-label="关卡进度">${SCENES.map((s,i)=>`<div class="progress-item ${i===game.round?'active':''} ${i<game.round?'complete':''}" ${i===game.round?'aria-current="step"':''}><span>${i<game.round?'✓':String(i+1).padStart(2,'0')}</span><small>${s.chapter}</small></div>`).join('')}</nav>`;}
function wallet(){return `<aside class="wallet" aria-label="虚构资金账本"><div class="wallet-heading"><span>你的虚构资金</span><span>本月</span></div><div class="cash-value">${money(game.cash)}</div><div class="wallet-row"><span>未来开支保护金</span><b>${money(game.reserve)}</b></div><div class="wallet-row"><span>开支已支付</span><b>${money(game.spent)}</b></div><div class="wallet-rule"></div><div class="wallet-row"><span>剩余损失预算</span><b>${money(riskLeft(game))}</b></div><p class="small-note">初始 ¥6,000 · 盈利不回补预算<br>每次投入 ≤ 剩余预算，且不动保护金。</p><details><summary>展开完整账目规则</summary><p>初始 ¥20,000，保护金 ¥10,000 = 两笔房租各 ¥3,000 + 必要生活费 ¥4,000。每轮统一结算，本金退回现金，再计入该轮盈亏与开支。</p><p>资金恒等式：当前现金 + 已付开支 = 初始本金 + 累计模拟盈亏。</p></details></aside>`;}
function probability(scene){return `<details class="probability"><summary>查看本关教学概率与规则</summary><div class="details-content"><p>以下是作者设定的离散教学模型，不是现实估计。看不看都不影响抽样。</p><table><caption>投资路径；等待的投资盈亏固定为 ¥0</caption><thead><tr><th>模拟分支</th><th>概率</th><th>本轮回报</th></tr></thead><tbody>${scene.outcomes.map(o=>`<tr><td>${o.label}</td><td>${o.prob}%</td><td>${o.bps>0?'+':''}${o.bps/100}%</td></tr>`).join('')}</tbody></table><p>每轮独立抽样，投入在本轮末结算。概率不是目标、保证或推荐。</p></div></details>`;}
function decisionPage(){const s=SCENES[game.round];return `<main id="main" tabindex="-1" class="game-page">${progress()}<div class="game-layout"><section class="scene"><div class="eyebrow"><span class="pill">情景 ${game.round+1} / 5</span><span>${s.day} · ${s.chapter}</span></div><h1>${nl(s.title)}</h1><p class="scene-lead">${s.lead}</p><article class="news-card ${s.theme}"><div class="news-label"><span>情景来信</span><span aria-hidden="true">${s.icon}</span></div><h2>${s.news}</h2><small>${s.source}</small></article><div class="character"><div class="avatar ${s.theme}">${s.avatar}</div><div><b>${s.person}</b><small>${s.role}</small><p>${s.quote}</p></div></div><section class="facts"><h2>你现在知道的</h2><ul>${s.known.map(x=>`<li>${x}</li>`).join('')}</ul></section><button class="investigate secondary" data-action="investigate" aria-expanded="${investigated}" aria-controls="evidence">${investigated?'✓ 材料已展开':'⌕  调查一下：'+s.evidenceTitle}<span>免费 / 不推进结果</span></button><section id="evidence" class="evidence" ${investigated?'':'hidden'}><h2>${s.evidenceTitle}</h2><ul>${s.evidence.map(x=>`<li>${x}</li>`).join('')}</ul><p>材料带来新信息，但不会消除不确定性。</p></section>${probability(s)}</section><div class="decision-sidebar">${wallet()}<form id="decision-form" class="decision-form" novalidate><div class="form-heading"><span class="tiny-label">决定存档 / 结果未揭晓</span><h2>这一轮，你怎么选？</h2></div><fieldset><legend>1. 选择投入金额</legend><div class="choices">${[0,100000,200000,300000].map(stake=>{const disabled=!allowedStakes(game).includes(stake);return `<label class="choice ${disabled?'unavailable':''}"><input type="radio" name="stake" value="${stake}" ${disabled?'disabled':''}><span><b>${stake===0?'这次先等一等':money(stake)}</b><small>${stake===0?'保留现金，也保留选择':disabled?'超出剩余预算':'本轮投入 / 本金有风险'}</small></span><span class="radio-dot" aria-hidden="true"></span></label>`;}).join('')}</div><p class="small-note">本轮允许的投入上限 ${money(maxStake(game))}，按千元档位选择。</p></fieldset><fieldset><legend>2. 把理由留下 <small>至少一项，可多选</small></legend><div class="reasons">${REASONS.map(r=>`<label><input type="checkbox" name="reason" value="${r.id}"><span>${r.label}</span></label>`).join('')}</div></fieldset><div class="note-field"><label for="note">${s.question}</label><textarea id="note" name="note" rows="3" maxlength="280" placeholder="选填，最多 280 字。只写虚构情景的想法，不要填写个人信息。"></textarea></div><fieldset><legend>3. 对这个决策过程，有多大把握？</legend><p class="small-note">指“选择符合约束、依据充分”的主观把握，<strong>不是赚钱概率</strong>。</p><div class="confidence">${[25,50,75,90].map(n=>`<label><input type="radio" name="confidence" value="${n}"><span>${n}%</span></label>`).join('')}</div></fieldset><fieldset id="update-field" ${investigated?'':'hidden'}><legend>新材料让你的判断如何变化？</legend><select name="update" aria-label="新材料如何改变判断"><option value="unchecked">暂未说明</option><option value="keep">保留原判断</option><option value="reduce">降低把握或规模</option><option value="increase">提高把握或规模</option></select></fieldset><p id="form-error" class="error" role="alert"></p><button class="primary commit-button" type="submit">锁定决定，看模拟结果 <span aria-hidden="true">→</span></button><p class="small-note center">理由会先存档。结果不会反过来改写它。</p></form></div></div></main>`;}
function feedbackHTML(r){return `<section class="process-feedback"><div class="section-heading"><div><span class="tiny-label">只看当时依据</span><h2>这次决定的过程反馈</h2></div><span class="neutral-pill">无能力评分</span></div><div class="feedback-grid">${r.feedback.map(f=>`<article class="feedback-item ${f.kind}"><span aria-hidden="true">${f.kind==='good'?'✓':f.kind==='notice'?'↳':'≈'}</span><div><h3>${f.title}</h3><p>${f.text}</p></div></article>`).join('')}</div><p class="small-note">反馈依据行为记录与明确规则生成，不评判你的投资智商，也不由收益加减分。</p></section>`;}
function recordHTML(r){return `<details class="record"><summary>打开结果揭晓前的决定原件</summary><div class="details-content"><p><strong>${r.decision.stake?`投入 ${money(r.decision.stake)}`:'等待，保留现金'}</strong> · 过程把握 ${r.decision.confidence}% · ${r.decision.investigated?'已调查':'未调查'}</p><p>理由：${r.decision.reasons.map(id=>REASONS.find(x=>x.id===id).label).join('；')}</p><p class="saved-note">${r.decision.note?esc(r.decision.note):'本轮没有填写额外笔记。'}</p></div></details>`;}
function pathsHTML(r){return `<section class="paths-section"><div class="section-heading"><div><span class="tiny-label">换运气，不换决定</span><h2>同一个选择，五条模拟路径</h2></div><span class="neutral-pill">本轮对照</span></div><p>沿用你刚才的 ${r.decision.stake?money(r.decision.stake)+' 投入':'等待决定'}、相同信息和相同理由，只换模型抽样。以下只比较这一轮，不是五个完整人生。</p><div class="path-grid">${r.paths.map((p,i)=>`<article class="path-card ${i===0?'selected-path':''}"><div><span>路径 ${'ABCDE'[i]}</span>${i===0?'<small>本次抽中</small>':'<small>平行模拟</small>'}</div><b class="${p.pnl>0?'positive':p.pnl<0?'negative':''}">${signed(p.pnl)}</b><span>${p.outcome.label}</span><div class="path-symbol" aria-hidden="true">${p.pnl>0?'↗':p.pnl<0?'↘':'→'}</div></article>`).join('')}</div><p class="small-note">五条路径为有放回抽样，可能重复；5 次展示的比例不是模型概率。等待时投资盈亏均为 ¥0，必要开支照常发生。</p><details class="probability"><summary>为什么可能没看到亏损路径？展开全部分支</summary><div class="details-content"><table><caption>全部教学分支，使用本次同一投入计算</caption><thead><tr><th>分支</th><th>设定概率</th><th>你的模拟盈亏</th></tr></thead><tbody>${SCENES[r.round].outcomes.map(o=>`<tr><td>${o.label}</td><td>${o.prob}%</td><td>${signed(pnlFor(r.decision.stake,o.bps))}</td></tr>`).join('')}</tbody></table></div></details></section>`;}
function resultPage(){const r=game.history.at(-1),s=SCENES[r.round];return `<main id="main" tabindex="-1" class="result-page">${progress()}<div class="result-banner"><div><div class="eyebrow"><span class="pill">情景 ${r.round+1} / 5 · 模拟已揭晓</span></div><h1>${r.decision.stake===0?'你选择了等待。':r.pnl>0?'这次，赚了。':r.pnl<0?'这次，亏了。':'这次，没有涨跌。'}</h1><p>${r.decision.stake===0?'现金没有参与价格波动；你仍可以复盘等待的理由。':r.pnl>0?'值得高兴。但这笔收益，还不能给全部理由盖章。':r.pnl<0?'这次结果不舒服。先回到当时信息，别急着给自己贴标签。':'平淡的结果，也值得检查当时的依据。'}</p></div><div class="result-number"><span>本轮模拟投资盈亏</span><strong>${signed(r.pnl)}</strong><small>${s.outcomes.find(o=>o.label===r.outcome.label).label} · 模型分支</small></div></div><div class="result-story"><span class="story-icon" aria-hidden="true">${s.icon}</span><p>${r.outcome.text}</p></div><div class="ledger-inline"><div><small>本轮前现金</small><b>${money(r.beforeCash)}</b></div><span>＋</span><div><small>模拟盈亏</small><b>${signed(r.pnl)}</b></div><span>−</span><div><small>${s.expenseLabel||'本轮必要开支'}</small><b>${money(r.expense)}</b></div><span>＝</span><div><small>当前现金</small><b>${money(r.afterCash)}</b></div></div>${recordHTML(r)}${feedbackHTML(r)}${pathsHTML(r)}<div class="reflection"><span aria-hidden="true">“</span><div><h2>把运气换掉，理由还站得住吗？</h2><p>试着用一句话回答。这里没有标准口号，只有当时的约束、已知信息和愿意更新的前提。</p></div></div><div class="page-actions"><span>${r.expense?`${s.expenseLabel} ${money(r.expense)} 已结清。`:'未来开支保护金完整保留。'}</span><button class="primary" data-action="next">${game.round===4?'看看整局复盘':'带着理由，进入下一关'} <span aria-hidden="true">→</span></button></div></main>`;}
function summaryPage(){const total=game.history.reduce((n,r)=>n+r.pnl,0);const r=game.history[replayIndex];return `<main id="main" tabindex="-1" class="summary-page"><div class="summary-hero"><span class="eyebrow">实验完成 / ${esc(game.seed)}</span><h1>带走你的理由，<br><em>不只是一串数字。</em></h1><p>这五次结果属于这一条模拟路径。你的复盘，值得多看一条路。</p></div><div class="summary-stats"><div><span>最终虚构现金</span><b>${money(game.cash)}</b></div><div><span>房租与生活费已付</span><b>${money(game.spent)}</b></div><div><span>整局模拟投资盈亏</span><b>${signed(total)}</b></div><div><span>累计亏损 / 损失预算</span><b>${money(game.lossUsed)} <small>/ ¥6,000</small></b></div></div><div class="summary-note"><span aria-hidden="true">✓</span><p>必要开支全部结清。每一次决定都守住了系统的资金边界；这只是本次约束记录，不是能力认证。</p></div><section class="replay"><div class="section-heading"><div><span class="tiny-label">回到作决定的那一刻</span><h2>逐关回放</h2></div><label class="replay-picker">选择情景<select id="replay-select">${SCENES.map((s,i)=>`<option value="${i}" ${i===replayIndex?'selected':''}>${i+1}. ${s.chapter}</option>`).join('')}</select></label></div><div class="replay-overview"><div><h3>${SCENES[r.round].title.replace('\n','')}</h3><p>${r.decision.stake?`投入 ${money(r.decision.stake)}`:'等待'} · 过程把握 ${r.decision.confidence}% · 本次盈亏 ${signed(r.pnl)}</p></div><span class="neutral-pill">记录已锁定</span></div>${recordHTML(r)}${feedbackHTML(r)}${pathsHTML(r)}</section><section class="takeaway"><span class="tiny-label">留给下一次</span><h2>一个可以带走的问题</h2><p>“如果这次的结果反过来，<br>我还会用同样的理由解释这个决定吗？”</p><span>这个试玩不证明你学会了投资，也不证明它具有教学效果。<br>所有概率与路径均为教学模型，不能外推到现实。</span></section><div class="page-actions"><button class="secondary" data-action="download">↓ 下载本次复盘</button><div class="replay-actions"><button class="secondary" data-action="same-seed">用相同编号重玩</button><button class="primary" data-action="new-seed">换一种运气再试 <span aria-hidden="true">↗</span></button></div></div><p class="small-note center">重玩从相同的虚构资金开始。改变编号会改变抽样；相同编号、关卡和选择得到相同账目。刷新会清空页面记录。</p></main>`;}
function bind(){
 app.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();action(el.dataset.action);}));
 document.querySelector('#decision-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{
  if(f.get('stake')===null) throw Error('请先选择投资金额，或选择“这次先等一等”。');
  if(f.get('confidence')===null) throw Error('请先记录你对决策过程的把握。');
  game=commit(game,{stake:Number(f.get('stake')),reasons:f.getAll('reason'),confidence:Number(f.get('confidence')),note:f.get('note')||'',investigated,update:investigated?f.get('update'):'unchecked'});render();
 }catch(err){const box=document.querySelector('#form-error');box.textContent=err.message;box.tabIndex=-1;box.focus();}});
 document.querySelector('#replay-select')?.addEventListener('change',e=>{replayIndex=Number(e.target.value);render(false);document.querySelector('#replay-select').focus();});
}
function begin(seed){game=newGame(seed);investigated=false;replayIndex=0;render();}
function action(name){
 if(name==='start'){try{begin(document.querySelector('#seed').value.trim());}catch(err){document.querySelector('#intro-error').textContent=err.message;}return;}
 if(name==='home'){if(game)openReset();else window.scrollTo({top:0,behavior:'smooth'});return;}
 if(name==='reset'){openReset();return;}
 if(name==='investigate'){if(!investigated){investigated=true;document.querySelector('#evidence').hidden=false;document.querySelector('#update-field').hidden=false;const b=document.querySelector('[data-action="investigate"]');b.setAttribute('aria-expanded','true');b.innerHTML='✓ 材料已展开<span>免费 / 不推进结果</span>';}return;}
 if(name==='next'){game=advance(game);investigated=false;render();return;}
 if(name==='same-seed'){begin(game.seed);return;}
 if(name==='new-seed'){const values=new Uint32Array(2);crypto.getRandomValues(values);begin('LAB-'+Array.from(values,n=>n.toString(36)).join('-').toUpperCase());return;}
 if(name==='download')download();
}
function openReset(){document.querySelector('#reset-dialog').showModal();document.querySelector('#cancel-reset').focus();}
document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-dialog').close();
document.querySelector('#confirm-reset').onclick=()=>{document.querySelector('#reset-dialog').close();game=null;investigated=false;replayIndex=0;render();};
function download(){const report={title:'你赚了钱，但你真的做对了吗？',version:'1.0.0',disclaimer:'虚构教学模型，不是现实预测、投资建议或能力评分；教学效果尚未验证。',seed:game.seed,model:{initialCents:INITIAL,riskBudgetCents:RISK_BUDGET,scenes:SCENES.map(s=>({id:s.id,title:s.title,outcomes:s.outcomes,expenseCents:s.expense}))},finalCashCents:game.cash,paidExpensesCents:game.spent,records:game.history};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='decision-lab-'+game.seed+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
render(false);
